require __DIR__.'/security.php';security_establish_session($ou);
function partnerFixture($title){global $pdo;$pdo->prepare("INSERT INTO mudaraba_contracts (shop_id,partner_name,project_title,capital_amount,total_sales_amount,total_profit_amount,paid_profit_to_partner,returned_capital,partner_profit_rate,shop_profit_rate,currency_code,status,profit_known) VALUES (?,'Synthetic partner',?,100,0,0,0,0,50,50,'AFN','active',1)")->execute([shop_id(),$title]);return (int)$pdo->lastInsertId();}
$contract=partnerFixture('Reviewed settlement');$cash=funds_create('Partner cash','cash','AFN',1000);partner_review($contract,0,0,'Reviewed with partner: no prior unpaid balances');$key=bin2hex(random_bytes(16));$receipt=partner_cash($contract,'funding',$cash,100,date('Y-m-d'),$key,'Partner funding receipt');check(partner_cash($contract,'funding',$cash,100,date('Y-m-d'),$key,'Partner funding receipt')===$receipt&&funds_balance($cash)==='1100.00','partner funding retry cannot duplicate cash or principal');
