$pdo->beginTransaction();$pdo->prepare('INSERT INTO sales (invoice_no,customer_name,total_amount,paid_amount,remaining_amount,profit,currency_code,shop_id,created_at) VALUES (?,?,150,150,0,50,?,?,?)')->execute(['PART-'.bin2hex(random_bytes(6)),'Partner test buyer','AFN',shop_id(),date('Y-m-d H:i:s')]);$sale=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO sale_items (sale_id,stock_id,product_name,quantity,unit_purchase_price,unit_expense,unit_sale_price,total_price,profit,unit,cost_amount,currency_code,cost_currency_code,shop_id) VALUES (?,?,?,10,10,0,15,150,50,?,100,?,?,?)')->execute([$sale,$stock,'Partner goods','unit','AFN','AFN',shop_id()]);$pdo->prepare('UPDATE stock SET quantity=0,inventory_value=0,capital_amount=0 WHERE id=? AND shop_id=?')->execute([$stock,shop_id()]);$pdo->prepare('UPDATE mudaraba_contracts SET total_sales_amount=150,total_profit_amount=50 WHERE id=? AND shop_id=?')->execute([$contract,shop_id()]);$_POST=['cash_account_id'=>$cash,'payment_currency_code'=>'AFN'];finance_currency_event('sales',$sale,'create');$_POST=[];$pdo->commit();check(partner_balances($contract)['profit']==='25.00','new sale accrues partner profit from the reviewed baseline');
partner_cash($contract,'profit',$cash,25,date('Y-m-d'),bin2hex(random_bytes(16)),'Profit paid to partner');partner_cash($contract,'principal',$cash,100,date('Y-m-d'),bin2hex(random_bytes(16)),'Principal repaid to partner');check(funds_balance($cash)==='1025.00'&&partner_balances($contract)['principal']==='0.00','principal and profit repayments use actual cash and clear obligations');
$caught=false;try{partner_cash($contract,'profit',$cash,1,date('Y-m-d'),bin2hex(random_bytes(16)),'Overpayment attempt');}catch(InvalidArgumentException $e){$caught=true;}check($caught,'partner profit cannot be paid beyond accrued obligations');
$caught=false;try{sale_return_post($sale,[],'Unreviewed distributed return',bin2hex(random_bytes(16)));}catch(InvalidArgumentException $e){$caught=true;}check($caught,'distributed partner return requires a current reviewed agreement');partner_review_return($sale,$contract,'Partner agrees to return and recover any overpaid profit');$reviewed=partner_return_allowed($sale,partner_contract($contract));check($reviewed,'owner approval binds the reviewed partnership balances');
$return=sale_return_post($sale,[],'Reviewed full partner return',bin2hex(random_bytes(16)));$b=partner_balances($contract);check($b['profit']==='0.00'&&$b['recovery']==='25.00','returned distributed profit becomes a recoverable partner receivable');check(!partner_return_allowed($sale,partner_contract($contract)),'changed contract totals invalidate the old return approval');$q=$pdo->prepare('SELECT id FROM customer_refunds WHERE shop_id=? AND return_id=?');$q->execute([shop_id(),$return]);sale_refund_pay((int)$q->fetchColumn(),$cash,150,bin2hex(random_bytes(16)),date('Y-m-d'));partner_cash($contract,'recovery',$cash,25,date('Y-m-d'),bin2hex(random_bytes(16)),'Recover overpaid profit');check(partner_balances($contract)['recovery']==='0.00','actual recovery receipt clears the partner receivable');
$caught=false;try{purchase_return_post((int)$purchase['id'],'Partner purchase return');}catch(InvalidArgumentException $e){$caught=true;}check($caught,'partner purchase return requires an ownership review');partner_review_purchase_return((int)$purchase['id'],$contract,'Partner agrees supplier return does not repay principal again');purchase_return_post((int)$purchase['id'],'Reviewed partner purchase return');finance_receive_supplier_refund((int)$purchase['id'],$cash,100,date('Y-m-d'),bin2hex(random_bytes(16)));check(funds_balance($cash)==='1000.00','sale return, partner recovery and supplier refund reconcile actual cash');partner_close($contract);check(partner_contract($contract)['status']==='settled','fully settled partnership closes only after stock and obligations are zero');
$second=partnerFixture('Ownership release');partner_review($second,0,0,'Partner has no remaining claims after reviewed settlement');$purchase=inventory_save_purchase(['purchase_mode'=>'single','purchase_request_key'=>bin2hex(random_bytes(16)),'name'=>'Release goods','unit'=>'unit','quantity'=>2,'purchase_price'=>10,'sale_price'=>15,'expenses'=>0,'currency_code'=>'AFN','purchase_date'=>date('Y-m-d'),'mudaraba_id'=>$second],$owner,false);$q=$pdo->prepare('SELECT stock_id FROM inventory_purchase_items WHERE purchase_id=? AND shop_id=?');$q->execute([$purchase['id'],shop_id()]);$stock=(int)$q->fetchColumn();$caught=false;try{inventory_transfer_create($stock,$a2,1,'Release attempt');}catch(InvalidArgumentException $e){$caught=true;}check($caught,'settled partner transfer still requires explicit release agreement');inventory_transfer_create($stock,$a2,1,'Approved ownership release',['ownership_released'=>'1','ownership_review'=>'Partner releases all claims on this transferred quantity']);$q=$pdo->prepare('SELECT id FROM inventory_transfers WHERE source_shop_id=? AND stock_id=? ORDER BY id DESC');$q->execute([shop_id(),$stock]);$transfer=(int)$q->fetchColumn();$old=shop_id();finance_in_branch($a2,fn()=>inventory_transfer_accept($transfer));$q=$pdo->prepare('SELECT mudaraba_id,partner_id FROM stock WHERE shop_id=? AND name=?');$q->execute([$a2,'Release goods']);$destination=$q->fetch();check($destination&&empty($destination['mudaraba_id'])&&empty($destination['partner_id']),'released goods arrive as business-owned stock after receiver approval');
$profitKey=bin2hex(random_bytes(16));$review=partner_review_profit($second,20,'Verified contract-currency profit from signed settlement',$profitKey);check(partner_review_profit($second,20,'Verified contract-currency profit from signed settlement',$profitKey)===$review&&partner_balances($second)['profit']==='10.00','verified profit review is idempotent and accrues only the partner share');
$q=$pdo->prepare('SELECT SUM(debit-credit) FROM journal_details WHERE shop_id=?');$q->execute([$old]);check(dec_units($q->fetchColumn())===0,'reviewed partnership workflows preserve balanced books');
echo "Reviewed partnership scenarios completed.\n";

